# MAT-Appendix Optimization V3.1 clean audited loader
import base64, hashlib, json, urllib.request, zlib

_OLD_BASE = "https://raw.githubusercontent.com/AzizulHakim00/MAT-Appendix/main/src/v3"
_OLD_PARTS = [f"{_OLD_BASE}/payload_{i:02d}.txt?v=v31-base" for i in range(1, 5)]
_OLD_SHA256 = "83c2b3a2b5f6a21857d6c3cfbfa4a64b3550175e7d197c22e3d975b39df653ac"
_NEW_SHA256 = "3f93c91dbc8b27316b74ec85bb40998fed6d3997bfc8509e421ccf37b44ee53f"
_PATCH_B64 = ""

encoded = "".join(urllib.request.urlopen(url).read().decode("utf-8").strip() for url in _OLD_PARTS)
old_source = zlib.decompress(base64.b64decode(encoded)).decode("utf-8")
old_actual = hashlib.sha256(old_source.encode("utf-8")).hexdigest()
if old_actual != _OLD_SHA256:
    raise RuntimeError(f"V3.1 base-source mismatch: expected {_OLD_SHA256}, got {old_actual}")

old_lines = old_source.splitlines(keepends=True)
ops = json.loads(zlib.decompress(base64.b64decode(_PATCH_B64)).decode("utf-8"))
new_lines = []
cursor = 0
for i1, i2, replacement in ops:
    new_lines.extend(old_lines[cursor:i1])
    new_lines.extend(replacement)
    cursor = i2
new_lines.extend(old_lines[cursor:])
source = "".join(new_lines)
new_actual = hashlib.sha256(source.encode("utf-8")).hexdigest()
if new_actual != _NEW_SHA256:
    raise RuntimeError(f"V3.1 patched-source mismatch: expected {_NEW_SHA256}, got {new_actual}")
print("Loaded MAT-Appendix Optimization V3.1 clean audited source.")
exec(compile(source, "MAT_Appendix_Optimization_V3_1_FullSource.py", "exec"))
